"""Render the hearing archive as ordinary, crawlable HTML."""
from datetime import datetime
from html import escape
from zoneinfo import ZoneInfo


def display_date(value):
    return datetime.fromisoformat(value).astimezone(ZoneInfo('America/Chicago')).strftime('%b %d, %Y · %I:%M %p %Z').replace(' 0',' ')


def hearing_card(event):
    badges = [event['chamber'], event['status']]
    if event.get('revised'): badges.append('Revised notice')
    if event.get('retrievalError'): badges.append('Refresh unavailable')
    header = ''.join('<span class="news-badge">'+escape(value)+'</span>' for value in badges)
    bill_links=[]
    for bill in event['relatedBills']:
        removed = bill in event.get('removedBillIds',[])
        bill_links.append('<a class="hearing-bill '+('removed' if removed else '')+'" href="/#bill/'+bill+'">'+escape(bill)+(' · removed from agenda' if removed else '')+'</a>')
    changes = ''.join('<li><time>'+display_date(change['at'])+'</time><strong>'+escape(change['kind'])+'</strong><p>'+escape(change['detail'])+'</p></li>' for change in reversed(event.get('changes',[])))
    warning = '<p class="hearing-warning">This notice was not listed in the latest upcoming-meetings check.  That does not establish cancellation; consult the official notice.</p>' if event.get('listedInUpcoming') is False else ''
    if event.get('dateFromFilename'):
        warning += '<p class="hearing-warning">The date below comes from the notice filename because the notice has no readable date.  Read the official notice before relying on it.</p>'
    if event.get('retrievalError'):
        warning += '<p class="hearing-warning">The latest notice retrieval failed.  These are the last verified details.</p>'
    searchable=' '.join([event['committee'],event['chamber'],event['location'],*event['relatedBills']])
    return f'''<article class="news-card hearing-card" data-hearing data-bills="{' '.join(event['relatedBills'])}" data-chamber="{escape(event['chamber'],quote=True)}" data-date="{event['date']}" data-status="{event['status']}" data-search="{escape(searchable,quote=True)}" id="{event['id']}"><div class="news-meta">{header}</div><h2>{escape(event['committee'])}</h2><dl class="hearing-facts"><div><dt>Date</dt><dd>{event['date']}</dd></div><div><dt>Official time & date</dt><dd>{escape(event['timeAndDate'])}</dd></div><div><dt>Location</dt><dd>{escape(event['location'])}</dd></div></dl><div class="hearing-bills">{''.join(bill_links)}</div>{warning}<div class="hearing-links"><a class="button primary" href="{event['noticeUrl']}" target="_blank" rel="noopener">Official notice ↗</a><a class="button" href="{event['pdfUrl']}" target="_blank" rel="noopener">Notice PDF ↗</a></div><p class="hearing-verified">Last verified {display_date(event['lastVerifiedAt'])}</p><details class="hearing-history"><summary>Notice history · {len(event.get('changes',[]))} entries</summary><ol>{changes}</ol></details></article>'''


def hearing_page(home, data, shell):
    today = datetime.now(ZoneInfo('America/Chicago')).date().isoformat()
    events = data['events']
    upcoming = sum(event['date']>=today and event['status']!='Canceled' for event in events)
    changes = sum(max(0,len(event.get('changes',[]))-1) for event in events)
    checked = display_date(data['updatedAt']) if data.get('updatedAt') else 'No successful source check yet'
    source_rows=''.join('<li><a href="'+escape(source['url'],quote=True)+'" target="_blank" rel="noopener">'+escape(source['label'])+' ↗</a><span>'+('Checked successfully' if source['status']=='ok' else 'Unavailable; prior records retained')+'</span></li>' for source in data['sources'])
    warning='<p class="news-warning">Some sources or notices could not be refreshed.  Existing records are retained, and missing results do not establish that no hearing is scheduled.</p>' if data['status']!='ok' else ''
    cards=''.join(hearing_card(event) for event in sorted(events,key=lambda event:event['date'],reverse=True))
    empty='<section class="content-card hearing-empty"><span aria-hidden="true">◷</span><h2>No matching 90R notices yet.</h2><p>The latest check found no 90R committee notices matching the tracked bills.  New matches will appear here as official notices are posted and checked.</p><a class="button" href="https://capitol.texas.gov/mnucommittees.aspx" target="_blank" rel="noopener">Check official committee schedules ↗</a></section>' if not events else ''
    content=f'''<section class="news-hero"><div><p class="eyebrow">90R · OFFICIAL COMMITTEE NOTICES</p><h1>Hearings & notices.</h1><p>Follow committee meetings involving the bills on this tracker.  See official schedules, agenda changes, and cancellations in one place.</p></div><span class="news-hero-mark" aria-hidden="true">◷</span></section><div class="news-freshness"><span class="source-dot"></span><span>Last source check {checked}</span><span>·</span><span>{data['trackedBillCount']} tracked bills</span><span>·</span><span>Daily monitoring</span></div>{warning}<p class="news-warning" id="hearing-stale" data-updated="{escape(data.get('updatedAt') or '',quote=True)}" hidden>The hearing snapshot is more than 36 hours old.  Check the official schedules for current information.</p><section class="stats" aria-label="Hearing totals"><div class="stat"><div class="stat-label">Matched notices</div><div class="stat-number">{len(events)}</div><p>Including retained notice history</p></div><div class="stat"><div class="stat-label">Upcoming meetings</div><div class="stat-number">{upcoming}</div><p>Excludes explicit cancellations</p></div><div class="stat stat-watch"><div class="stat-label">Changes detected</div><div class="stat-number">{changes}</div><p>Updates after initial discovery</p></div></section><form id="hearing-search-form" class="search simple-search section-search" role="search"><label class="sr-only" for="hearing-search">Search hearings</label><input id="hearing-search" type="search" placeholder="Search by bill, committee, or location" autocomplete="off"><button type="submit" aria-label="Search hearings"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"></circle><path d="m16 16 5 5"></path></svg></button></form><details class="search-options hearing-search-options"><summary>More filters</summary><section class="hearing-filter-panel hearing-options-panel"><label>Chamber<select id="hearing-chamber"><option value="">All chambers</option><option>House</option><option>Senate</option><option>Joint</option></select></label><label>Show<select id="hearing-period"><option value="upcoming">Upcoming</option><option value="all">All notices & history</option><option value="canceled">Canceled</option><option value="past">Past meetings</option></select></label><label class="hearing-watch"><input id="hearing-watch" type="checkbox"> My watchlist only</label><button class="button" id="hearing-export">Export CSV ↓</button></section></details><p class="news-count" id="hearing-count" aria-live="polite">{len(events)} matched notices</p><p class="hearing-tip">Meeting times may be conditional, including “upon adjournment.”  The official wording is preserved.  Check the linked notice before attending or submitting testimony; schedules can change between daily updates.</p><div class="news-list" id="hearing-list">{cards}</div>{empty}<section class="content-card" id="hearing-filter-empty" hidden><h2>No notices match these filters.</h2><p id="hearing-empty-detail">Try all notices, another bill, or a different chamber.</p><button class="button" id="hearing-reset">Reset filters</button></section><section class="news-method content-card"><h2>How hearing monitoring works</h2><p>Each daily check reads official House and Senate meeting feeds and House, Senate, and joint-committee upcoming-meeting lists.  It opens 90R notices and matches bill numbers against the bills on this tracker.  Notices from earlier sessions are excluded.</p><p>Matched notices retain a change history.  Explicit cancellation notices and bills removed from an agenda are labeled.  A notice disappearing from an upcoming list is not treated as a cancellation.  Previously matched notices remain available under “All notices & history.”  Tracking begins when a notice is first detected; this is not a complete historical archive.</p><p>The watchlist filter uses the same bills saved in this browser.  Monitoring does not send email or text alerts, and it does not establish testimony or filing deadlines.  Committee notices are checked daily; chamber floor calendars, minutes, and witness lists are not separately ingested.</p><details><summary>Official sources & check status</summary><ul>{source_rows}</ul><p>{data['discoveredNoticeCount']} current 90R notice links found; {len(data.get('noticeErrors',[]))} notice retrieval errors.</p></details></section><script src="/hearings.js?v=hearings-search-20261112" defer></script>'''
    return shell(home,'Texas 90R bill hearings and committee notices','Track Texas legislative hearings and committee notices for religious liberty bills, including schedule revisions, agenda removals, and cancellations.','/hearings/',content)
